android.extraProguardRules:
# WorkManager (pulled in by react-native-maps) loads Room's generated WorkDatabase_Impl by name at startup.
# Without these, R8 strips/rewrites it and the release app crashes on launch.
-keep class androidx.work.** { *; }
-keep class androidx.room.** { *; }
-keep class * extends androidx.room.RoomDatabase { *; }
